action.command:
python3 -I -B -c 'from pathlib import Path; import subprocess,tempfile,json; p=Path("benchmark/native/job/native_job.py"); source=p.read_text(); r=subprocess.run(["python3","-I","-B",str(p),"--self-test"],capture_output=True,text=True); print("BASELINE",json.dumps({"exit":r.returncode,"stdout":r.stdout,"stderr":r.stderr})); mutations=[("changed source","if before != after:","if False:"),("missing output","if missing or extra:","if extra:"),("extra output","if missing or extra:","if missing:"),("networking enabled","if network != '\''none'\'':","if False:"),("changed working copy","if before != work_before or work_before != work_after:","if False:")]; results=[]; tmp=tempfile.TemporaryDirectory(prefix="review-native-job-"); root=Path(tmp.name); [(print("GIT",json.dumps({"args":args,"exit":g.returncode,"stdout":g.stdout,"stderr":g.stderr}))) for args in [["git","rev-parse","HEAD"],["git","log","-1","--format=%H %s","--","benchmark/native/job/"],["git","log","-2","--format=%H %s","--stat","--","benchmark/native/job/"]] for g in [subprocess.run(args,capture_output=True,text=True)]]; 
for index,(label,old,new) in enumerate(mutations):
 assert source.count(old)==1,(label,source.count(old))
 target=root/(str(index)+".py"); target.write_text(source.replace(old,new,1)); run=subprocess.run(["python3","-I","-B",str(target),"--self-test"],capture_output=True,text=True); results.append({"disabled_check":label,"replacement":{"old":old,"new":new},"exit":run.returncode,"stdout":run.stdout,"stderr":run.stderr})
print("MUTATION_PROBES",json.dumps(results,indent=2)); tmp.cleanup()'
